	'upd_req_writable_help' => "PHP draait als „%1\$s” en mag deze mappen alleen lezen: ze horen bij de gebruiker die ze heeft geüpload (bijv. via SFTP), met de gebruikelijke rechten 755 (anderen: alleen lezen).\nOplossen via SSH (map: %2\$s):\n• sudo chown -R %1\$s %2\$s – de bestanden horen bij PHP (via SFTP dan alleen leesbaar)\n• of gedeeld: sudo chown -R jouwuser:%1\$s %2\$s en chmod 2775 op de mappen, 664 op de bestanden\nZonder SSH, in de SFTP-client (bijv. FileZilla: rechtsklik → Bestandsrechten): de mappen op 777 zetten (lezen, schrijven, uitvoeren voor iedereen – „uitvoeren” bij een map betekent „mag erin”), recursief, alleen mappen. Update installeren, daarna terug naar 755.\nOf handmatig bijwerken: de bestanden van nunext.zip over de oude uploaden.",
