	'smp_title' => 'Voorbeeldgegevens',
	'smp_back' => 'Beheertools',
	'smp_card_hint' => 'Gebruikers, toegangsniveaus en formulieren met elk objecttype – om uit te proberen en te testen. Alles begint met sample_.',
	'smp_intro' => 'Installeert een kleine voorbeeldapplicatie: 5 gebruikers met 5 toegangsniveaus, formulieren voor klanten, producten en bestellingen, en één formulier met elk objecttype en elke opmaak. Elk record, elke tabel en elke id begint met sample_, zodat alles volledig kan worden verwijderd. De formulieren zijn in het formaat van nuBuilder Forte geschreven en openen ook in nuBuilder Forte. Er horen ook vier dashboards bij: op de startpagina van de voorbeeldgebruikers, in het klantenformulier (tabblad Statistics) en in het voorbeeld-startformulier.',
	'smp_intro_home' => 'Startpagina\'s van gebruikers: sample_sales (Dario) krijgt een verkoopplek met favorieten en een groep alleen voor de machtiging sample_discount, sample_manager (Carla) een pagina met twee tabbladen en een groep alleen voor team Lead, sample_editor (Ben) een invoerlijst met een rapport alleen voor bepaalde functies. sample_viewer en sample_secure houden de automatische pagina met hun formulieren en rapporten.',
