	'rd_help_text' => 'Sleep velden van links naar een sectie, of klik op Veld / Tekst / Rechthoek / Lijn / Afbeelding. De secties worden in deze volgorde afgedrukt: rapportkop (één keer), paginakop (elke pagina), groepskoppen, detail (elke rij), groepsvoeten, paginavoet, rapportvoet.\\nVerplaats objecten met de muis (ook naar een andere sectie) of met de pijltjestoetsen (Shift = 4 mm, Alt = 0,25 mm); de grepen wijzigen de grootte. Shift-klik of een kader om er meerdere te kiezen, daarna de uitlijnknoppen.\\nCtrl+Z / Ctrl+Y ongedaan maken en opnieuw, Ctrl+C / Ctrl+V kopiëren, Ctrl+D dupliceert, Del verwijdert, Ctrl+S slaat op.\\nVelden: een kolom, SUM(kolom) of AVERAGE(a, b) – sommen per sorteergroep. Teksten mogen #page#, #pages#, #code#, #description#, #nu_date# en elke hashvariabele bevatten (bijv. velden van het startformulier).\\nEen waarde die begint met #B#rrggbb| of #F#rrggbb| krijgt die achtergrond- / tekstkleur (voorwaardelijke opmaak vanuit de gegevensbron).\\nHet voorbeeld drukt de huidige lay-out af met lege criteria; de lay-out wordt in het formaat van nuBuilder Forte opgeslagen.',
